// The DFT-D3 reference tables (src/d3_data.cpp, generated by tools/gen_d3_data.py
// from tad-dftd3; see NOTICE). In D3's own units, as published; d3.cpp converts
// them to Angstrom and eV once, when a D3 is made.
#pragma once

namespace pet::d3data {

constexpr int kMaxZ = 104;   // atomic numbers 1..103 (0 is a dummy)
constexpr int kMaxRef = 7;   // reference systems per element, at most
constexpr int kR0Pairs = (kMaxZ - 1) * kMaxZ / 2;

extern const int nref[kMaxZ];
extern const int cnref_e4[kMaxZ * kMaxRef];  // x 10^4
extern const double rcov_bohr[kMaxZ];
extern const double r4r2_bohr[kMaxZ];
extern const int r0_e4[kR0Pairs];            // Angstrom x 10^4, lower triangle
extern const int c6_off[kR0Pairs];
extern const int c6_e4[];                    // hartree bohr^6 x 10^4, packed blocks
extern const int c6_count;

inline int pair_index(int i, int j) {  // i, j >= 1, either order
  if (i < j) {
    const int t = i;
    i = j, j = t;
  }
  return i * (i - 1) / 2 + j - 1;
}

struct Functional {
  const char* name;
  bool has_bj;
  double bj_s6, bj_s8, bj_a1, bj_a2;  // a2 in bohr
  bool has_zero;
  double zero_s6, zero_s8, zero_rs6, zero_rs8;
};
extern const Functional functionals[];
extern const int n_functionals;

struct Alias {
  const char* name;
  const char* target;
};
extern const Alias aliases[];
extern const int n_aliases;

}  // namespace pet::d3data
